<template>
  <q-dialog :model-value="modelValue" @update:model-value="$emit('update:modelValue', $event)">
    <q-card class="issue-form-card">
      <q-card-section class="issue-form-header">
        <div class="text-h6">{{ isEdit ? $t('edit_issue') : $t('create_issue') }}</div>
        <q-space />
        <q-btn icon="close" flat round dense @click="$emit('update:modelValue', false)" />
      </q-card-section>

      <q-separator />

      <q-card-section class="issue-form-body" style="display: flex; flex-direction: column; gap: 8px;">
        <q-input
          v-model="formData.title"
          :label="$t('title') + ' *'"
          outlined
          dense
          :rules="[val => !!val || $t('title_required')]"
        />
        <q-input
          v-model="formData.description"
          :label="$t('description')"
          outlined
          dense
          type="textarea"
          :input-style="{ minHeight: '60px' }"
          autogrow
        />
        <div class="row q-gutter-sm">
          <q-select
            v-model="formData.priority"
            :options="priorityOptions"
            :label="$t('priority')"
            outlined
            dense
            emit-value
            map-options
            class="col"
          />
          <AssigneePicker
            v-model="formData.assignee_id"
            :agents="[]"
            :humans="humanPickerOptions"
            :label="$t('assignee')"
            class="col"
          />
        </div>
        <div class="row q-gutter-sm">
          <q-select
            v-model="formData.mission_id"
            :options="missionOptions"
            :label="$t('mission')"
            outlined
            dense
            emit-value
            map-options
            clearable
            class="col"
          />
        </div>
      </q-card-section>

      <q-separator />

      <q-card-actions align="right" class="q-pa-md">
        <f-btn
          appearance="flat"
          :label="$t('cancel')"
          @click="$emit('update:modelValue', false)"
        />
        <f-btn
          appearance="primary"
          :label="$t('save')"
          :loading="saving"
          @click="onSave"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import type { DocNetIssue } from 'src/@types/docnet';
import AssigneePicker, { type AssigneeOption } from '../../shared/AssigneePicker.vue';
import {
  issueTypeOptions as buildIssueTypeOptions,
  priorityOptions as buildPriorityOptions,
  statusOptions as buildStatusOptions,
} from '../../shared/docnet-labels';

export interface AgentOption {
  id: string;
  name: string;
  role?: string;
  workload?: number;
}

export interface MissionOption {
  id: string;
  name: string;
}

export interface FormData {
  title: string;
  description: string;
  status: string;
  priority: string;
  type: string;
  assignee_id: string;
  mission_id: string;
  due_date: string;
  tagsString: string;
}

function buildDefaultForm(task: Partial<DocNetIssue> | null): FormData {
  return {
    title: task?.title || '',
    description: task?.description || '',
    status: task?.status || 'todo',
    priority: task?.priority || 'medium',
    type: task?.type || 'task',
    assignee_id: task?.assignee_id || '',
    mission_id: task?.mission_id || '',
    due_date: task?.due_date || '',
    tagsString: (task?.tags || []).join(', '),
  };
}

export default defineComponent({
  name: 'IssueForm',
  components: { AssigneePicker },
  props: {
    modelValue: {
      type: Boolean,
      default: false,
    },
    task: {
      type: Object as PropType<Partial<DocNetIssue> | null>,
      default: null,
    },
    missions: {
      type: Array as PropType<MissionOption[]>,
      default: () => [],
    },
    saving: {
      type: Boolean,
      default: false,
    },
  },
  emits: ['update:modelValue', 'save'],
  data() {
    return {
      formData: buildDefaultForm(this.task) as FormData,
    };
  },
  computed: {
    isEdit(): boolean {
      return this.task !== null;
    },
    statusOptions() {
      return buildStatusOptions(this.$t);
    },
    priorityOptions() {
      return buildPriorityOptions(this.$t);
    },
    typeOptions() {
      return buildIssueTypeOptions(this.$t);
    },
    humanPickerOptions(): AssigneeOption[] {
      return [
        { label: 'Amier Haider', value: 'user-001', type: 'human' as const },
        { label: 'Sarah Mueller', value: 'user-002', type: 'human' as const },
      ];
    },
    missionOptions() {
      return this.missions.map((m) => ({
        label: m.name,
        value: m.id,
      }));
    },
  },
  watch: {
    task: {
      handler(newTask: Partial<DocNetIssue> | null) {
        this.formData = buildDefaultForm(newTask);
      },
      deep: true,
    },
  },
  methods: {
    onSave() {
      if (!this.formData.title.trim()) {
        return;
      }
      const tags = this.formData.tagsString
        .split(',')
        .map((t) => t.trim())
        .filter(Boolean);

      const payload: Record<string, any> = {
        title: this.formData.title.trim(),
        description: this.formData.description.trim(),
        status: this.formData.status,
        priority: this.formData.priority,
        type: this.formData.type,
        tags,
      };

      if (this.formData.assignee_id) {
        payload.assignee_id = this.formData.assignee_id;
      }
      if (this.formData.mission_id) {
        payload.mission_id = this.formData.mission_id;
      }
      if (this.formData.due_date) {
        payload.due_date = this.formData.due_date;
      }

      this.$emit('save', payload);
    },
  },
});
</script>

